package com.bananalab.lite;
import org.json.*;import java.io.*;import java.nio.file.*;import java.util.*;
public final class Stage78SelfExamCheck{
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static String page(String topic,int sentences){StringBuilder s=new StringBuilder();String[] things={"resina","corteza","semilla","raíz","hoja","flor","savia","espina"};for(int i=0;i<sentences;i++){String name=topic+"ina"+(char)('a'+i%26)+(i/26);s.append("La ").append(name).append(" es una ").append(things[i%things.length]).append(" ficticia del valle número ").append(i+1).append(". Los artesanos de Quirema").append(i).append(" la usan para sellar vasijas de barro cocido. Su olor recuerda a la canela tostada del mercado viejo. ");}return s.toString();}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);BananaTransformer m;try(InputStream in=Files.newInputStream(root.resolve("assets/lector3/lector3.bin"))){m=BananaTransformer.container(in);}
  CreatorPersistenceCheck.Fake c=new CreatorPersistenceCheck.Fake();NotebookDisk disk=NotebookDisk.of(c);
  disk.put("Libro largo",new StringReader(page("truf",260)),"https://example.com/libro","web");disk.put("Nota corta",new StringReader(page("molv",3)),"https://example.com/nota","web");disk.put("Corrección del usuario",new StringReader("La capital de Quirema es Altamisa, no Belorado. El puerto principal de Quirema se llama Tindal."),"user","user");
  List<NotebookDisk.Doc> order=LectorTraining.ordered(disk);check(order.size()==3&&order.get(0).title.equals("Corrección del usuario")&&!order.get(2).origin.equals("user"),"the user's corrections are studied first");
  NotebookDisk.Doc book=null;for(NotebookDisk.Doc d:order)if(d.title.equals("Libro largo"))book=d;int blocks=0;while(!disk.index.slice(book.id,blocks,1).isEmpty())blocks++;check(blocks>=6,"long document has several blocks: "+blocks);
  // Training order never hands out a set-aside block
  JSONObject state=new JSONObject().put("cursors",new JSONObject()).put("accepted",0).put("rejected",0).put("tokens",0).put("grown",0);List<String> served=new ArrayList<>();NotebookDisk.Hit hit;int guard=0;
  while((hit=LectorTraining.next(disk,state))!=null&&guard++<200){check(hit.doc.title.equals("Corrección del usuario")||!LectorTraining.reserved(hit.ordinal),"reserved block served for training");served.add(hit.doc.title+":"+hit.ordinal);LectorTraining.advance(state,hit);}
  check(served.get(0).startsWith("Corrección del usuario")&&served.contains("Libro largo:0")&&served.contains("Libro largo:5")&&!served.contains("Libro largo:4")&&!served.contains("Libro largo:9"),"studied blocks skip every fifth: "+served);check(LectorTraining.next(disk,state)==null,"library exhausted");
  // Extra passes only with the charger, bounded per day
  long now=20000L*LearningPlan.DAY_MS+5;check(!LectorTraining.repass(state,now,false,8)&&LectorTraining.next(disk,state)==null,"no extra pass on battery");check(LectorTraining.repass(state,now,true,2)&&LectorTraining.next(disk,state)!=null,"charging starts another pass");
  while((hit=LectorTraining.next(disk,state))!=null)LectorTraining.advance(state,hit);check(LectorTraining.repass(state,now,true,2),"second pass of the day");while((hit=LectorTraining.next(disk,state))!=null)LectorTraining.advance(state,hit);check(!LectorTraining.repass(state,now,true,2)&&state.getInt("passes")==2,"daily limit of passes");check(LectorTraining.repass(state,now+LearningPlan.DAY_MS,true,2),"limit resets the next day");while((hit=LectorTraining.next(disk,state))!=null)LectorTraining.advance(state,hit);
  // Exam: set-aside blocks, studied blocks and the user's corrections
  List<LectorExam.Item> items=LectorExam.items(m,disk,state,LectorExam.ITEMS,0);int held=0,fixed=0,studied=0;for(LectorExam.Item i:items){if(i.correction)fixed++;else if(i.held)held++;else studied++;check(i.probe.sentences.contains(i.sentence)&&!i.probe.own,"exam answers are literal sentences of the saved text");check(!i.held||LectorTraining.reserved(i.ordinal),"held items come only from reserved blocks");}
  check(items.size()>=8&&items.size()<=LectorExam.ITEMS&&held>=2&&studied>=2&&fixed>=1,"exam mix: "+items.size()+" held "+held+" studied "+studied+" fixed "+fixed);
  List<LectorExam.Item> other=LectorExam.items(m,disk,state,LectorExam.ITEMS,3);boolean differs=false;for(int i=0;i<Math.min(items.size(),other.size());i++)if(!items.get(i).question.equals(other.get(i).question))differs=true;check(differs,"questions rotate between exams");
  JSONObject fresh=new JSONObject().put("cursors",new JSONObject());check(LectorExam.items(m,disk,fresh,LectorExam.ITEMS,0).size()==fixed,"nothing studied yet: only the corrections can be asked");
  ReadingWeights.Governor free=new ReadingWeights.Governor(){public void check(){}};LectorExam.Score score=LectorExam.grade(m,items,free);
  check(score.total==items.size()&&score.right+score.failed.size()==score.total&&score.heldTotal==held&&score.fixedTotal==fixed&&score.loss>0&&!Double.isNaN(score.loss),"grading counts");check(score.right>=EXPECTED_RIGHT,"reader exam on invented text: "+score.right+" of "+score.total);
  LectorExam.Score same=LectorExam.grade(m,items,free);check(same.right==score.right&&Math.abs(same.loss-score.loss)<1e-9,"grading is deterministic");
  // A model that reads worse loses against the best one on the same questions
  BananaTransformer damaged;try(InputStream in=Files.newInputStream(root.resolve("assets/lector3/lector3.bin"))){damaged=BananaTransformer.container(in);}Random noise=new Random(5);for(float[] row:damaged.embedding)for(int j=0;j<row.length;j++)row[j]+=(float)(noise.nextGaussian()*.6);LectorExam.Score bad=LectorExam.grade(damaged,items,free);
  check(bad.loss>score.loss&&bad.worseThan(score)&&!score.worseThan(bad)&&!score.worseThan(same),"damaged model is detected as worse: "+bad.right+"/"+bad.loss+" vs "+score.right+"/"+score.loss);
  JSONObject log=new JSONObject(state.toString());check(LectorExam.record(log,damaged,bad,score)&&log.getJSONArray("exams").getJSONObject(0).getBoolean("rolledBack")&&log.getInt("sinceExam")==0&&log.getInt("examRound")==1,"worse successor triggers the return to the best checkpoint");
  int studiedFailures=0;for(LectorExam.Item i:bad.failed)if(!i.held)studiedFailures++;check(log.getJSONArray("review").length()==Math.min(studiedFailures,LectorExam.REVIEW)&&studiedFailures>0,"failed studied blocks are queued for review, held ones are not");
  JSONObject first=log.getJSONArray("review").getJSONObject(0);hit=LectorTraining.next(disk,log);check(hit!=null&&hit.doc.id.equals(first.getString("id"))&&hit.ordinal==first.getInt("ordinal")&&log.getBoolean("reviewing"),"review blocks are served before new ones");int before=log.getJSONObject("cursors").getJSONObject(hit.doc.id).getInt("ordinal");LectorTraining.advance(log,hit);check(log.getJSONObject("cursors").getJSONObject(hit.doc.id).getInt("ordinal")==before,"a review does not move the reading cursor");
  check(!LectorExam.record(new JSONObject(state.toString()),m,score,same)&&!LectorExam.record(new JSONObject(state.toString()),m,score,null),"an equal model or a first exam keeps the current reader");
  for(int i=0;i<40;i++)LectorExam.record(log,m,score,null);check(log.getJSONArray("exams").length()==LectorExam.HISTORY,"bounded exam history");String history=LectorExam.history(log);check(history.contains(score.right+"/"+score.total)&&history.contains("Bloques en repaso"),"history text: "+history);check(LectorExam.history(new JSONObject()).contains("todavía ninguno"),"empty history");
  check(LectorExam.due(c,new JSONObject().put("sinceExam",LectorExam.EVERY))&&!LectorExam.due(c,new JSONObject().put("sinceExam",LectorExam.EVERY-1)),"exam cadence");
  check(KnowledgeNotebook.parse("tomate un examen").kind.equals("reader_exam")&&KnowledgeNotebook.parse("Hacé una autoprueba").kind.equals("self_check")&&KnowledgeNotebook.parse("progreso del lector").kind.equals("reader_status"),"chat phrases");
  // Self-test: logic checks pass anywhere; asset checks are reported, not hidden
  LinkedHashMap<String,SelfCheck.Step> steps=SelfCheck.steps(c);check(steps.size()==9,"self-test steps");for(String name:new String[]{"Reglas de enlaces y subenlaces","Pedidos del cuaderno","Filtro de ejemplos Java","Extracción de texto de una página","Búsqueda en lo guardado","Biblioteca de documentos"})steps.get(name).run();
  String report=SelfCheck.run(c);check(report.startsWith("Autoprueba: 6 de 9")&&report.contains("✗ Lector neuronal")&&report.contains("✓ Biblioteca de documentos")&&report.contains("reinstalar la APK anterior"),"host context lacks model assets and the report says so: "+report);check(SelfCheck.last(c).startsWith("Autoprueba: 6 de 9"),"last result is kept for the panel");
  String[] control=LectorTraining.CONTROLS[0];List<String> controlSentences=Arrays.asList(KnowledgeNotebook.chunks(control[0]));Lector.Pick controlPick=Lector.select(m,null,controlSentences,control[1],8);check(controlPick!=null&&controlSentences.get(controlPick.index).equals(control[2]),"the control sentence used by the device self-test is chosen by the shipped reader");
  System.out.println("PASS Stage78 self-exam: corrections first, one block in five set aside, charging passes, rotating exam ("+score.right+"/"+score.total+" exact on invented text, "+score.heldRight+"/"+score.heldTotal+" on unseen blocks), worse-model detection and return to the best checkpoint, review queue, bounded history, phrases and self-test report");
 }
 static final int EXPECTED_RIGHT=0;
}
